'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const base=path.resolve(__dirname,'../collection-2026-11-01'),dir=path.join(base,'web-assets'),refs=new Set(),records=[];
for(const f of fs.readdirSync(dir).filter(f=>f.startsWith('transsaas-')&&f.endsWith('.js'))){const t=fs.readFileSync(path.join(dir,f),'utf8');for(const m of t.matchAll(/"(\/assets\/[^" ]+\.(?:png|jpg|webp|svg))"/g))refs.add(m[1]);}
(async()=>{const queue=[...refs];let i=0;await Promise.all(Array.from({length:4},async()=>{while(i<queue.length){const pathname=queue[i++],url='https://transsaas-h5-ap1.iflyoversea.com'+pathname,r={url,kind:'documentation',checkedAt:new Date().toISOString()};try{const res=await fetch(url,{signal:AbortSignal.timeout(25000)});r.httpStatus=res.status;r.contentType=res.headers.get('content-type');if(!res.ok||!r.contentType?.startsWith('image/'))throw Error('Not an image: HTTP '+res.status);const b=Buffer.from(await res.arrayBuffer());r.bytes=b.length;r.sha256=crypto.createHash('sha256').update(b).digest('hex');r.file='web-assets/bavvo-image-'+path.basename(pathname);fs.writeFileSync(path.join(base,r.file),b);r.status='downloaded';}catch(e){r.status='unavailable';r.error=e.message;}records.push(r);}}));fs.writeFileSync(path.join(base,'bavvo-help-images.json'),JSON.stringify(records,null,2)+'\n');console.log(JSON.stringify(records.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{})));})().catch(e=>{console.error(e);process.exitCode=1});
